package com.yeeyuan;
import java.util.*;
import java.time.*;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import org.springframework.http.MediaType;
import static com.yeeyuan.Db.*;
@Component
public class Workers {
 final Db db;final Payments payments;final Orders orders;final Settings config;
 public Workers(Db db,Payments payments,Orders orders,Settings config){this.db=db;this.payments=payments;this.orders=orders;this.config=config;}
 @Scheduled(fixedDelay=1000) public void jobs(){for(String table:List.of("outbox_event","webhook_inbox")){String initial=table.equals("outbox_event")?"READY":"RECEIVED";var jobs=db.jdbc.queryForList("UPDATE "+table+" SET status='PROCESSING',locked_until=now()+interval '45 seconds',lease_token=gen_random_uuid(),attempt_count=attempt_count+1 WHERE id IN (SELECT id FROM "+table+" WHERE ((status=? AND next_attempt_at<=now()) OR (status='PROCESSING' AND locked_until<now())) ORDER BY next_attempt_at LIMIT 5 FOR UPDATE SKIP LOCKED) RETURNING *",initial);for(var j:jobs){try{if(table.equals("webhook_inbox"))event(j);else outbox(j);db.jdbc.update("UPDATE "+table+" SET status=?,locked_until=NULL WHERE id=? AND lease_token=?",table.equals("outbox_event")?"SENT":"DONE",j.get("id"),j.get("lease_token"));}catch(RuntimeException e){int count=((Number)j.get("attempt_count")).intValue();long wait=Math.min(1800,5L*(1L<<Math.min(8,count)));db.jdbc.update("UPDATE "+table+" SET status=?,locked_until=NULL,next_attempt_at=now()+(? * interval '1 second'),last_error_code=? WHERE id=? AND lease_token=?",count>=10?"DEAD_LETTER":initial,wait,e.getClass().getSimpleName(),j.get("id"),j.get("lease_token"));}}}}
 @SuppressWarnings("unchecked") void event(Map<String,Object> j){var p=db.decode(j.get("payload"));if(str(j,"provider").equals("LINE")){String type=str(p,"type");if(p.get("source") instanceof Map<?,?> source&&source.get("userId")!=null&&Set.of("follow","unfollow").contains(type)){String sub=String.valueOf(source.get("userId"));db.jdbc.update("INSERT INTO app_user(kind,line_subject,line_following) VALUES('CUSTOMER',?,?) ON CONFLICT(line_subject) DO UPDATE SET line_following=excluded.line_following",sub,type.equals("follow"));}return;}
  if(!str(j,"event_type").startsWith("charge."))return;Map<String,Object> data=(Map<String,Object>)p.get("data");if(data==null)return;String id=str(data,"id");var c=payments.retrieve(id);var attempts=db.jdbc.queryForList("SELECT id FROM payment_attempt WHERE provider_charge_id=? OR ref_id=?",id,str(c,"ref_id"));if(attempts.isEmpty())throw new Problem(409,"UNMATCHED_EVENT","Charge mapping not available yet");payments.apply(uuid(attempts.get(0),"id"),c);
 }
 void outbox(Map<String,Object> job){UUID aggregate=uuid(job,"aggregate_id");if(str(job,"topic").equals("CREATE_CHARGE")){payments.generate(aggregate);return;}if(!str(job,"topic").equals("LINE_STATUS"))return;if(job.get("expires_at")!=null&&time(job,"expires_at").isBefore(Instant.now()))return;var o=db.one("SELECT o.*,u.line_subject,u.line_following FROM orders o JOIN app_user u ON u.id=o.customer_id WHERE o.id=?",aggregate);if(!Boolean.TRUE.equals(o.get("line_following"))||config.lineChannelAccessToken().isBlank())return;String milestone=str(db.decode(job.get("payload")),"milestone");if(Set.of("CANCELLED","EXPIRED","COMPLETED").contains(str(o,"status")))return;String text="ออเดอร์ "+str(o,"code")+(milestone.equals("READY")?" พร้อมรับแล้วค่ะ":" ยืนยันชำระแล้ว ร้านรับออเดอร์แล้วค่ะ")+"\nติดตาม: "+config.publicAppUrl()+"/orders/?id="+aggregate;
  RestClient.create().post().uri("https://api.line.me/v2/bot/message/push").header("Authorization","Bearer "+config.lineChannelAccessToken()).header("X-Line-Retry-Key",str(job,"id")).contentType(MediaType.APPLICATION_JSON).body(Map.of("to",str(o,"line_subject"),"messages",List.of(Map.of("type","text","text",text)))).retrieve().toBodilessEntity();
 }
 @Scheduled(fixedDelay=60000,initialDelay=10000) public void reconcile(){for(var a:db.jdbc.queryForList("SELECT * FROM payment_attempt WHERE status IN ('CREATING','UNKNOWN','PENDING') AND next_check_at<=now() ORDER BY next_check_at LIMIT 30")){UUID id=uuid(a,"id");try{if(config.mockPayments()){if(time(a,"expires_at").isBefore(Instant.now()))db.jdbc.update("UPDATE payment_attempt SET status='EXPIRED' WHERE id=? AND status='PENDING'",id);}else if(a.get("provider_charge_id")!=null)payments.apply(id,payments.retrieve(str(a,"provider_charge_id")));else if(str(a,"status").equals("UNKNOWN"))payments.generate(id);}catch(RuntimeException ignored){/* Leave truth unresolved; no replacement charge is issued. */}finally{db.jdbc.update("UPDATE payment_attempt SET next_check_at=now()+interval '60 seconds' WHERE id=?",id);}}for(var o:db.jdbc.queryForList("SELECT id FROM orders WHERE status='AWAITING_PAYMENT' AND payment_deadline<now() LIMIT 50"))try{orders.expire(uuid(o,"id"));}catch(RuntimeException ignored){}}
}
